(() => {
 'use strict';
 if(!document.documentElement.dataset.nkRouteDocument&&!(window!==window.parent&&new URL(location.href).searchParams.has('nk_frame'))&&!new URL(location.href).searchParams.has('nk_direct'))return;
 const rune=id=>'<svg viewBox="0 0 64 64" aria-hidden="true"><use href="/assets/rock-icons-v5.svg#'+id+'"/></svg>';
 const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const slabGrid=document.querySelector('.slab-purpose-grid');
 if(slabGrid){
  const game=document.createElement('div');game.className='stone-sort ancient-game';game.dataset.game='allocation';
  game.innerHTML='<div class="game-heading"><div><span class="eyebrow">PLAY WITH THE PRINCIPLE / SLABS</span><h3>Ten stones.<br>Every one has a purpose.</h3></div><p>Each stone is one tenth of a payday. Follow the 50 / 30 / 20 path, or carve a plan of your own.</p></div><div class="stone-pile" role="group" aria-label="Unplaced allocation stones"></div><p class="game-instruction">Pick a stone, then a hollow. Pick a filled hollow to take a stone back. <span class="desktop-instruction">You can also drag stones on desktop.</span></p><div class="allocation-landscape"></div><div class="game-footer"><p class="game-status" role="status" aria-live="polite"></p><div><button class="game-link" data-allocation-free>Carve your own path</button><button class="game-link" data-allocation-reset>Reset stones ↻</button><button class="game-release" data-allocation-release disabled>Release the payday ↓</button></div></div>';
  slabGrid.replaceWith(game);
  const camps=[['everyday','Everyday','sun',5],['rent','Rent','shelter',3],['travel','Travel','compass',0],['reserve','Reserve','cairn',2]],placements=Array(10).fill(null);let selected=null,free=false;
  const pile=game.querySelector('.stone-pile'),land=game.querySelector('.allocation-landscape'),status=game.querySelector('.game-status'),release=game.querySelector('[data-allocation-release]');
  function render(){
   pile.innerHTML=placements.map((place,i)=>place?'<span class="pebble-space" aria-hidden="true"></span>':'<button class="allocation-pebble '+(selected===i?'is-picked':'')+'" data-pebble="'+i+'" draggable="true" aria-label="Pick up stone '+(i+1)+'" aria-pressed="'+(selected===i)+'" style="--stone-turn:'+((i*17)%24-12)+'deg"><span aria-hidden="true">'+String(i+1).padStart(2,'0')+'</span></button>').join('');
   land.innerHTML=camps.map(([id,name,icon,target])=>{const count=placements.filter(p=>p===id).length;return '<button class="allocation-hollow hollow-'+id+'" data-camp="'+id+'" aria-label="Place in '+name+', '+count+' stones"><span class="hollow-symbol">'+rune(icon)+'</span><span class="hollow-name">'+name+'</span><span class="hollow-pebbles" aria-hidden="true">'+Array.from({length:count},(_,i)=>'<i style="--pebble-order:'+i+'"></i>').join('')+'</span><strong>'+count*10+'<small>%</small></strong><span class="hollow-goal">'+(free?'YOUR OWN PATH':target*10+'% PATH')+'</span></button>'}).join('');
   const left=placements.filter(p=>!p).length,correct=camps.every(([id,n,ic,target])=>placements.filter(p=>p===id).length===target);
   status.textContent=left?left+' stone'+(left===1?'':'s')+' still to place.':free?'Every stone has a place. Your allocation adds up to 100%.':correct?'A clear path: 50% Everyday, 30% Rent, 20% Reserve.':'All stones placed. Shift them to follow the 50 / 30 / 20 path, or make this your own plan.';
   release.disabled=left>0||(!free&&!correct);game.dataset.complete=String(!release.disabled);game.querySelector('[data-allocation-free]').textContent=free?'Follow the 50 / 30 / 20 path':'Carve your own path';
  }
  function place(camp){if(selected!==null){placements[selected]=camp;selected=null}else{const index=placements.lastIndexOf(camp);if(index>=0)placements[index]=null}render()}
  game.addEventListener('click',e=>{const stone=e.target.closest('[data-pebble]'),camp=e.target.closest('[data-camp]');if(stone){const i=Number(stone.dataset.pebble);selected=selected===i?null:i;render();pile.querySelector('[data-pebble="'+i+'"]').focus()}else if(camp){const id=camp.dataset.camp;place(id);land.querySelector('[data-camp="'+id+'"]').focus()}});
  game.addEventListener('dragstart',e=>{const stone=e.target.closest('[data-pebble]');if(!stone)return;selected=Number(stone.dataset.pebble);e.dataTransfer.setData('text/plain',String(selected));e.dataTransfer.effectAllowed='move'});
  game.addEventListener('dragover',e=>{const camp=e.target.closest('[data-camp]');if(camp){e.preventDefault();camp.classList.add('is-over')}});game.addEventListener('dragleave',e=>e.target.closest('[data-camp]')?.classList.remove('is-over'));
  game.addEventListener('drop',e=>{const camp=e.target.closest('[data-camp]');if(camp){e.preventDefault();place(camp.dataset.camp)}});
  game.querySelector('[data-allocation-reset]').onclick=()=>{placements.fill(null);selected=null;render()};game.querySelector('[data-allocation-free]').onclick=()=>{free=!free;render()};
  release.onclick=()=>{if(release.disabled)return;game.classList.remove('is-flowing');requestAnimationFrame(()=>game.classList.add('is-flowing'));status.textContent='One arrival, four clear purposes. Every part follows the allocation you chose.'};render();
 }
 const promo=!document.body.classList.contains('landing-page')&&document.querySelector('.product-feature-row');
 if(promo){
  const section=document.createElement('section');section.id='float-playground';section.className='float-playground section-pad ancient-game';section.dataset.game='float';
  section.innerHTML='<div class="game-heading"><div><span class="eyebrow">PLAY WITH THE PRINCIPLE / FLOAT</span><h2>Find your<br>natural level.</h2></div><p>Pour a little from the bowl. Watch the threshold bring it back to your target, until the daily cap draws the line.</p></div><div class="float-landscape"><div class="float-inscription"><span class="rune-heading">'+rune('ripple')+'</span><strong>Just enough.<br>By your rules.</strong><p>The bowl represents the card. Your wider account stays separate. These levels explain the rule.</p><dl><div><dt>Target</dt><dd>150</dd></div><div><dt>Refill below</dt><dd>40</dd></div><div><dt>Daily cap</dt><dd>300</dd></div></dl></div><div class="float-bowl"><svg viewBox="0 0 360 360" role="img" aria-label="An interactive stone bowl showing the Float level"><defs><pattern id="bowl-stone" patternUnits="userSpaceOnUse" width="360" height="360"><image href="/assets/limestone-texture.webp" width="360" height="360" preserveAspectRatio="xMidYMid slice"/><rect width="360" height="360" fill="#73552f" opacity=".65"/></pattern><clipPath id="float-pool-clip"><path d="M81 82Q168 31 273 83L301 173Q306 255 254 302L112 306Q57 268 54 187Z"/></clipPath><linearGradient id="float-water" x2="0" y2="1"><stop stop-color="#d2ac6c"/><stop offset="1" stop-color="#72502d"/></linearGradient></defs><path class="bowl-outer" d="M67 61 128 28 221 24 290 65 327 153 329 231 286 315 218 341 112 334 42 282 25 197 36 110Z"/><path class="bowl-edge" d="M81 82Q168 31 273 83L301 173Q306 255 254 302L112 306Q57 268 54 187Z"/><g clip-path="url(#float-pool-clip)"><rect class="pool-water" x="30" y="0" width="310" height="360" fill="url(#float-water)"/><path class="pool-ripple" d="M32 4Q85-5 136 4T240 4T340 4"/></g><path class="threshold-scratch" d="M67 266L96 263M265 264L291 262"/><text x="180" y="180" class="pool-number" text-anchor="middle">150</text><text x="180" y="202" class="pool-caption" text-anchor="middle">CARD LEVEL</text></svg><img class="float-bowl-rim" src="/assets/float-bowl-frame.webp" width="1254" height="1254" alt="" loading="eager"></div><div class="float-play-controls"><label for="float-play-level">MOVE THE WATERLINE <output id="float-play-output">150</output></label><input id="float-play-level" type="range" min="0" max="220" step="10" value="150" aria-label="Float guide card level"><div class="float-used"><span>Refilled today</span><strong><span id="float-play-used">0</span> / 300</strong><div><i></i><i></i><i></i><i></i><i></i><i></i></div></div><button class="game-release" data-pour>Pour out 30 ↓</button><button class="game-link" data-float-reset>Reset the bowl ↻</button><p class="game-status" role="status" aria-live="polite">Lower the bowl below 40 to see Float refill to 150.</p></div></div>';
  promo.closest('section').before(section);let level=150,used=0,timer;const slider=section.querySelector('input'),status=section.querySelector('.game-status');
  function paint(){section.querySelector('.pool-water').style.transform='translateY('+(310-level*1.1)+'px)';section.querySelector('.pool-ripple').style.transform='translateY('+(310-level*1.1)+'px)';section.querySelector('.pool-number').textContent=level;section.querySelector('#float-play-output').textContent=level;section.querySelector('#float-play-used').textContent=used;slider.value=level;section.querySelectorAll('.float-used i').forEach((e,i)=>e.classList.toggle('used',used>i*50));section.dataset.level=String(level);section.dataset.used=String(used)}
  function check(){clearTimeout(timer);if(level<40){status.textContent='Below the threshold. Checking the daily cap…';timer=setTimeout(()=>{const refill=150-level;if(used+refill<=300){used+=refill;level=150;paint();status.textContent='Back to 150. Float refilled '+refill+' within the daily cap.'}else status.textContent='The daily cap holds the line. This refill would exceed 300, so Float stays paused.'},reduce?0:500)}else status.textContent='Above the refill threshold. Your level stays where you put it.'}
  slider.addEventListener('input',()=>{level=Number(slider.value);paint();check()});section.querySelector('[data-pour]').onclick=()=>{level=Math.max(0,level-30);paint();check()};section.querySelector('[data-float-reset]').onclick=()=>{clearTimeout(timer);level=150;used=0;paint();status.textContent='A fresh day. Lower the bowl below 40 to see Float refill to 150.'};paint();
 }
 const flow=document.querySelector('.architecture-flow');
 if(flow){
  const game=document.createElement('div');game.className='desk-path ancient-game';game.dataset.game='escrow';game.dataset.stage='account';
  game.innerHTML='<div class="game-heading"><div><span class="eyebrow">FOLLOW THE PRINCIPLE / CARD DESK</span><h3>Every load<br>finds an outcome.</h3></div><p>Guide a carved stone through the escrow path. Choose what happens, then trace the route back to settlement or refund.</p></div><svg class="escrow-trail" viewBox="0 0 820 255" role="img" aria-label="A load travels from the account to escrow, acceptance, then settlement or refund"><defs><pattern id="escrow-stone" patternUnits="userSpaceOnUse" width="80" height="80"><image href="/assets/limestone-texture.webp" width="80" height="80"/><rect width="80" height="80" fill="#ad8b52" opacity=".4"/></pattern></defs><path class="trail-track" d="M70 130Q173 113 300 130T520 130Q615 130 741 56M300 130Q462 231 741 202M520 130Q634 210 741 202"/><g class="milestone" transform="translate(70 130)"><path d="M-30-20-4-31 27-17 34 8 15 29-21 25-35 4Z"/><text y="57">ACCOUNT</text></g><g class="milestone" transform="translate(300 130)"><path d="M-30-20-4-31 27-17 34 8 15 29-21 25-35 4Z"/><text y="57">ESCROW</text></g><g class="milestone" transform="translate(520 130)"><path d="M-30-20-4-31 27-17 34 8 15 29-21 25-35 4Z"/><text y="57">ACCEPTED</text></g><g class="milestone" transform="translate(741 56)"><path d="M-30-20-4-31 27-17 34 8 15 29-21 25-35 4Z"/><text y="57">SETTLED</text></g><g class="milestone" transform="translate(741 202)"><path d="M-30-20-4-31 27-17 34 8 15 29-21 25-35 4Z"/><text y="44">REFUNDED</text></g><g class="load-stone"><path d="M-13-10 3-15 16-4 11 13-8 15-17 3Z"/><path d="m-6-4 7-3 6 8-6 7-8-3Z"/></g></svg><div class="desk-decision"><div><span class="eyebrow" data-path-label>01 / IN YOUR ACCOUNT</span><p class="game-status" role="status" aria-live="polite"></p></div><div class="path-choices"></div></div><button class="game-link" data-path-reset>Trace another path ↻</button>';
  const facts=flow.nextElementSibling;if(facts?.classList.contains('foundation-grid'))facts.remove();flow.replaceWith(game);
  const stages={account:{at:[70,130],label:'01 / IN YOUR ACCOUNT',text:'Your keys control the starting point. A load enters escrow before a card-program request.',choices:[['escrow','Place in escrow →']]},escrow:{at:[300,130],label:'02 / HELD IN ESCROW',text:'The load is waiting for acceptance. No card-program request is made before this step.',choices:[['accepted','Partner accepts →'],['unaccepted-refund','Advance 10 minutes ↻']]},accepted:{at:[520,130],label:'03 / ACCEPTED',text:'An accepted load can settle or refund. If no outcome arrives within 72 hours, a time-based refund path opens.',choices:[['settled','Confirm settlement →'],['accepted-refund','Advance 72 hours ↻']]},settled:{at:[741,56],label:'04 / SETTLED',text:'The escrow is settled. Card credit still requires reconciliation: the chain proves escrow state, not the card program’s credit.',choices:[]},'unaccepted-refund':{at:[741,202],label:'04 / REFUNDED',text:'Ten minutes passed without acceptance. Anyone can trigger the refund of the escrowed amount and fees to the payer.',choices:[]},'accepted-refund':{at:[741,202],label:'04 / REFUNDED',text:'Seventy-two hours passed after acceptance without an outcome. Anyone can trigger the time-based refund path.',choices:[]}};
  const narrow=matchMedia('(max-width: 650px)');let active='account';const mobilePoints={account:[55,65],escrow:[180,65],accepted:[300,150],settled:[270,300],'unaccepted-refund':[90,300],'accepted-refund':[90,300]};
  function go(id){active=id;const s=stages[id],point=narrow.matches?mobilePoints[id]:s.at;game.dataset.stage=id;game.querySelector('.load-stone').style.transform='translate('+point[0]+'px,'+point[1]+'px)';game.querySelector('[data-path-label]').textContent=s.label;game.querySelector('.game-status').textContent=s.text;game.querySelector('.path-choices').innerHTML=s.choices.map(([next,text])=>'<button class="game-release" data-path-next="'+next+'">'+text+'</button>').join('')}
  game.addEventListener('click',e=>{const next=e.target.closest('[data-path-next]');if(next)go(next.dataset.pathNext)});game.querySelector('[data-path-reset]').onclick=()=>go('account');function layout(){game.querySelector('.escrow-trail').setAttribute('viewBox',narrow.matches?'0 0 360 380':'0 0 820 255');game.querySelector('.trail-track').setAttribute('d',narrow.matches?'M55 65Q120 40 180 65T300 150Q310 230 270 300M180 65Q180 200 90 300M300 150Q190 240 90 300':'M70 130Q173 113 300 130T520 130Q615 130 741 56M300 130Q462 231 741 202M520 130Q634 210 741 202');[...game.querySelectorAll('.milestone')].forEach((g,i)=>{const id=['account','escrow','accepted','settled','unaccepted-refund'][i],p=narrow.matches?mobilePoints[id]:stages[id].at;g.setAttribute('transform','translate('+p[0]+' '+p[1]+')')});go(active)}narrow.addEventListener('change',layout);layout();
 }
})();
